/**
 * Kurze Theorie zu jedem Schulthema („Das Wichtigste“).
 * Wird auf der Theorie-Seite und in der Lektion (Buch-Symbol) gezeigt,
 * zusammen mit automatisch erzeugten Beispielen und Lernkarten.
 */
export interface Guide { intro: Txt; points: Txt[] }

type P = [string, string];
const g = (intro: P, ...points: P[]): Guide => ({ intro: tx(intro[0], intro[1]), points: points.map((p) => tx(p[0], p[1])) });

